// main.go - FreeLang REST API 서버 진입점

package main

import (
	"flag"
	"log"

	"backend/api"
)

func main() {
	port := flag.String("port", "8080", "서버 포트")
	dbPath := flag.String("db", "freelang.db", "SQLite 데이터베이스 경로")
	env := flag.String("env", "dev", "실행 환경 (dev/prod)")
	flag.Parse()

	config := api.ServerConfig{
		Port:      *port,
		DBPath:    *dbPath,
		Env:       *env,
		JWTSecret: "your-secret-key",
	}

	server, err := api.NewServer(config)
	if err != nil {
		log.Fatalf("[Error] 서버 생성 실패: %v", err)
	}

	defer server.Close()

